"""
Rule-based diagnostic engine.

Every explanation is produced by predefined if/else rules over the outcomes
DNSGuard actually observed. The engine never invents a root cause: where the
evidence is compatible with several causes it says so and lists them as
possibilities together with checks that could tell them apart.
"""
from __future__ import annotations

from dns_engine import response_classifier as rc

SEVERITY_ORDER = {"ok": 0, "info": 1, "warning": 2, "error": 3}

DISCLAIMER = (
    "These explanations are generated by fixed rules from the DNS responses observed in this test. "
    "They describe what the evidence shows; where several causes are possible, they are listed as "
    "possibilities rather than conclusions."
)

# --------------------------------------------------------------------------
# Rule table: one entry per observed outcome category.
# Placeholders: {domain} {rtype} {resolver} {ip} {timeout} {family}
# --------------------------------------------------------------------------
RULES: dict[str, dict] = {
    rc.SUCCESS: {
        "status": "NOERROR",
        "title": "Resolution succeeded",
        "severity": "ok",
        "simple": "{resolver} returned {rtype} record(s) for {domain}.",
        "technical": (
            "The response header carried RCODE 0 (NOERROR) and the answer section contained an {rtype} "
            "RRset owned by the query name (or by the final target of its CNAME chain). The address(es) "
            "are {family} addresses."
        ),
        "checks": [
            "Compare the returned addresses with the other resolver to check consistency.",
            "Note the TTL: it tells you how long resolvers may cache this answer.",
            "Repeat the test later to see whether latency and answers stay stable.",
        ],
    },
    rc.NODATA: {
        "status": "NOERROR (no {rtype} record)",
        "title": "Name answered, but no {rtype} record",
        "severity": "info",
        "simple": "The resolver answered without error, but {domain} has no {rtype} record.",
        "technical": (
            "RCODE was 0 (NOERROR) but the answer section held no {rtype} RRset for the query name or its "
            "CNAME target. Per RFC 2308 this is a 'NODATA' response: the name exists in DNS, the requested "
            "type does not. This is a valid answer, not a resolver failure."
        ),
        "checks": [
            "Try the other record type ({other_rtype}) for the same name.",
            "Check whether a different hostname (for example with or without 'www.') publishes the record.",
            "If the record was added recently, cached negative answers may persist until their TTL expires.",
        ],
    },
    rc.NXDOMAIN: {
        "status": "NXDOMAIN",
        "title": "Domain does not exist (per the response)",
        "severity": "error",
        "simple": "The DNS resolver indicates that this domain name does not exist.",
        "technical": (
            "RCODE 3 (NXDOMAIN, 'Name Error' in RFC 1035) means the authoritative data says the queried "
            "name does not exist for any record type. Resolvers may cache this negative answer for the "
            "SOA-defined negative TTL (RFC 2308)."
        ),
        "checks": [
            "Verify the domain spelling.",
            "Check the domain registration (WHOIS / registrar) and whether its delegation is in place.",
            "Retry the lookup using another resolver.",
        ],
    },
    rc.SERVFAIL: {
        "status": "SERVFAIL",
        "title": "Resolver reported a server failure",
        "severity": "error",
        "simple": "{resolver} could not complete the lookup and returned a server failure.",
        "technical": (
            "RCODE 2 (SERVFAIL) means the recursive resolver was unable to produce an answer. Common "
            "situations include unreachable or misconfigured authoritative name servers, a broken "
            "delegation, or DNSSEC validation failure. The response alone does not identify which applies."
        ),
        "checks": [
            "Retry the lookup with the other resolver and compare.",
            "Trace the delegation from the root (e.g. `dig +trace {domain}`) to see where it breaks.",
            "Test with DNSSEC checking disabled (`dig +cd {domain} @{ip}`); if that works, a DNSSEC problem is likely.",
        ],
    },
    rc.REFUSED: {
        "status": "REFUSED",
        "title": "Resolver refused the query",
        "severity": "error",
        "simple": "{resolver} refused to answer this query.",
        "technical": (
            "RCODE 5 (REFUSED) means the server declined to perform the operation for policy reasons. "
            "Public resolvers rarely refuse ordinary A/AAAA queries, so the response may have come from an "
            "intermediate device that intercepts DNS traffic."
        ),
        "checks": [
            "Check whether your network redirects or filters DNS traffic on port 53.",
            "Retry from a different network.",
            "Compare with the other resolver.",
        ],
    },
    rc.TIMEOUT: {
        "status": "TIMEOUT",
        "title": "No response within the timeout",
        "severity": "error",
        "simple": "No reply arrived from {resolver} within {timeout} seconds.",
        "technical": (
            "The UDP query to {ip}:53 received no matching response before the configured timeout. "
            "This is not a DNS response code: the query or reply may have been lost, delayed or blocked "
            "on the network path, or the resolver may not have answered in time."
        ),
        "checks": [
            "Check general internet connectivity.",
            "Check whether a firewall blocks outbound UDP/TCP port 53.",
            "Increase the timeout and run the test again.",
        ],
    },
    rc.NETWORK_ERROR: {
        "status": "NETWORK ERROR",
        "title": "Query could not be sent or received",
        "severity": "error",
        "simple": "The query to {resolver} failed at the network level.",
        "technical": (
            "The operating system reported a socket error while sending to or receiving from {ip}:53 "
            "(for example 'network unreachable' or 'connection refused'). No DNS response was obtained."
        ),
        "checks": [
            "Check that this machine has a working network connection and a default route.",
            "Check firewall rules for outbound port 53.",
            "Retry the test.",
        ],
    },
    rc.OTHER_ERROR: {
        "status": "OTHER DNS ERROR",
        "title": "Unexpected DNS response",
        "severity": "warning",
        "simple": "{resolver} returned an unusual response that DNSGuard does not treat as a valid answer.",
        "technical": (
            "The response used an uncommon response code (for example FORMERR or NOTIMP) or could not be "
            "parsed. It is handled as a failed attempt."
        ),
        "checks": [
            "Retry the lookup.",
            "Compare with the other resolver.",
            "Inspect the attempt details for the exact response code.",
        ],
    },
}


def _fmt(text: str, ctx: dict) -> str:
    try:
        return text.format(**ctx)
    except (KeyError, IndexError):
        return text


def _context(domain, rtype, meta, timeout) -> dict:
    return {
        "domain": domain,
        "rtype": rtype,
        "other_rtype": "AAAA" if rtype == "A" else "A",
        "family": "IPv6 (128-bit)" if rtype == "AAAA" else "IPv4 (32-bit)",
        "resolver": meta.get("name", meta.get("key", "The resolver")),
        "ip": meta.get("ip", "?"),
        "timeout": f"{timeout:g}" if isinstance(timeout, (int, float)) else str(timeout),
    }


def _render_rule(category: str, ctx: dict) -> dict:
    rule = RULES.get(category, RULES[rc.OTHER_ERROR])
    return {
        "category": category,
        "status": _fmt(rule["status"], ctx),
        "title": _fmt(rule["title"], ctx),
        "severity": rule["severity"],
        "simple": _fmt(rule["simple"], ctx),
        "technical": _fmt(rule["technical"], ctx),
        "checks": [_fmt(c, ctx) for c in rule["checks"]],
    }


def diagnose_attempt(attempt: dict, timeout: float = 2.0) -> dict:
    meta = {"name": attempt.get("resolver_name"), "ip": attempt.get("resolver_ip")}
    ctx = _context(attempt.get("domain"), attempt.get("record_type"), meta, timeout)
    return _render_rule(attempt.get("category"), ctx)


def diagnose_resolver(meta: dict, summary: dict, attempts: list[dict], domain: str,
                      record_type: str, timeout: float) -> dict:
    ctx = _context(domain, record_type, meta, timeout)
    counts = summary.get("category_counts", {})
    total = summary.get("total", 0)
    dominant = summary.get("dominant_category") or rc.OTHER_ERROR
    evidence: list[str] = []
    notes: list[str] = []

    if total == 0:
        return {
            "category": None, "status": "NO DATA", "title": "No attempts recorded", "severity": "info",
            "simple": "No attempts were recorded for this resolver.", "technical": "", "checks": [],
            "evidence": [], "notes": [], "resolver": meta,
        }

    if len(counts) == 1:
        diag = _render_rule(dominant, ctx)
    elif counts.get(rc.SUCCESS) and any(rc.outcome_of(c) == rc.OUTCOME_FAILURE for c in counts):
        failed = summary.get("failed", 0)
        diag = {
            "category": "INTERMITTENT",
            "status": "INTERMITTENT",
            "title": "Intermittent failures observed",
            "severity": "warning",
            "simple": (f"{ctx['resolver']} answered successfully in {summary['successful']} of {total} attempts; "
                       f"{failed} attempt(s) failed."),
            "technical": (
                "The same query produced different outcomes within one test run. Because successful answers "
                "were also received, the name itself resolves; the failures are consistent with transient "
                "conditions such as packet loss, resolver load or upstream timeouts, but this test cannot "
                "establish which."
            ),
            "checks": [
                "Repeat the test with more attempts to see whether the failure rate is stable.",
                "Increase the timeout if the failures are timeouts.",
                "Compare with the other resolver over the same period.",
            ],
        }
    else:
        diag = _render_rule(dominant, ctx)
        diag["title"] = "Mixed outcomes observed"
        diag["severity"] = "warning"
        diag["simple"] = f"{ctx['resolver']} returned different kinds of answers across attempts."

    # Evidence: what was actually seen.
    evidence.append(
        "Outcomes: " + ", ".join(f"{rc.CATEGORY_LABELS.get(c, c)} × {n}" for c, n in counts.items())
    )
    if summary.get("median_latency_ms") is not None:
        evidence.append(
            f"Median latency {summary['median_latency_ms']:.2f} ms over {summary['latency_samples']} successful attempt(s)."
        )
    if summary.get("records"):
        evidence.append(f"{record_type} records: {', '.join(summary['records'])}")
    if summary.get("ttl_min") is not None:
        evidence.append(f"Answer TTL observed: {summary['ttl_min']}–{summary['ttl_max']} s.")

    # Extra, evidence-backed notes.
    chain = summary.get("cname_chain") or []
    if chain:
        hops = " → ".join([chain[0]["name"]] + [h["target"] for h in chain])
        notes.append(f"The name is an alias (CNAME chain: {hops}). Records were taken from the final target.")
        if dominant == rc.NODATA:
            notes.append(f"The CNAME target has no {record_type} record, so the alias does not resolve to an address of this type.")
    if dominant == rc.NODATA and record_type == "AAAA":
        notes.append("No IPv6 address is published for this name. IPv6-only clients could not reach it by this name; IPv4 clients are unaffected.")
    if dominant == rc.NODATA and record_type == "A":
        notes.append("No IPv4 address is published for this name. It may be IPv6-only, or the name may be used for other record types (e.g. MX, TXT).")
    if summary.get("tcp_fallbacks"):
        notes.append(f"{summary['tcp_fallbacks']} response(s) were truncated over UDP and retried over TCP (TC flag set).")
    if summary.get("distinct_record_sets", 0) > 1:
        notes.append("Different attempts returned different address sets, which is typical of DNS load balancing.")

    # Caching observation: first successful attempt notably slower than the rest.
    succ = [a for a in attempts if a.get("category") == rc.SUCCESS and a.get("latency_ms") is not None]
    if len(succ) >= 3:
        first = succ[0]["latency_ms"]
        rest = sorted(a["latency_ms"] for a in succ[1:])
        mid = rest[len(rest) // 2] if len(rest) % 2 else (rest[len(rest) // 2 - 1] + rest[len(rest) // 2]) / 2
        if mid > 0 and first > 2 * mid and first - mid > 5:
            notes.append(
                f"The first successful attempt ({first:.1f} ms) was much slower than the rest (median {mid:.1f} ms). "
                "This pattern is consistent with a resolver cache miss followed by cached answers, but other "
                "explanations (e.g. connection warm-up, path variation) are possible."
            )

    diag.update({"evidence": evidence, "notes": notes, "resolver": meta})
    return diag


def _cross_resolver(diags: dict[str, dict], summaries: dict[str, dict], meta: dict[str, dict],
                    domain: str, record_type: str) -> list[dict]:
    if len(diags) < 2:
        return []
    (ka, da), (kb, db) = list(diags.items())[:2]
    na, nb = meta[ka]["name"], meta[kb]["name"]
    ca, cb = da["category"], db["category"]
    out = []

    def add(severity, title, text, checks=None):
        out.append({"severity": severity, "title": title, "text": text, "checks": checks or []})

    if ca == cb == rc.SUCCESS:
        add("ok", "Both resolvers resolved the name",
            f"{na} and {nb} both returned {record_type} records for {domain}.")
    elif ca == cb == rc.NXDOMAIN:
        add("error", "Both resolvers report NXDOMAIN",
            f"Two independent public resolvers agree that {domain} does not exist. This is strong evidence "
            "that the name is not present in public DNS at the time of the test.",
            ["Verify the spelling.", "Check registration and name-server delegation with the registrar."])
    elif {ca, cb} == {rc.NXDOMAIN, rc.SUCCESS}:
        ok, nx = (na, nb) if ca == rc.SUCCESS else (nb, na)
        add("warning", "Resolvers disagree on whether the name exists",
            f"{ok} returned records while {nx} returned NXDOMAIN. Possible explanations include a recently "
            "created or changed domain with a cached negative answer, or resolver-side filtering policy. "
            "This test cannot establish which.",
            ["Repeat the test after the negative-cache TTL has expired.", "Check the authoritative servers directly."])
    elif ca == cb == rc.TIMEOUT:
        add("error", "Neither resolver responded",
            "No response arrived from either resolver. Since two independent services both failed, the "
            "evidence points towards the local network path (connectivity, firewall or DNS filtering on "
            "port 53) rather than one resolver, but it does not prove it.",
            ["Check internet connectivity.", "Check firewall rules for UDP/TCP 53.", "Try another network."])
    elif rc.TIMEOUT in (ca, cb) and rc.SUCCESS in (ca, cb):
        to, ok = (na, nb) if ca == rc.TIMEOUT else (nb, na)
        add("warning", f"Only {to} timed out",
            f"{ok} answered, so DNS traffic was able to leave this network. {to} did not respond in time; "
            "possible reasons include a network path or filtering issue specific to that resolver's address, "
            "or temporary unavailability.",
            [f"Retry {to} with a longer timeout.", f"Check whether {to}'s IP is blocked on this network."])
    elif ca == cb == rc.SERVFAIL:
        add("error", "Both resolvers returned SERVFAIL",
            "When independent resolvers both fail, the problem is more likely on the domain's authoritative "
            "side (unreachable name servers, broken delegation or DNSSEC errors) than in either resolver.",
            [f"Run `dig +trace {domain}`.", f"Try `dig +cd {domain}` to test whether DNSSEC validation is involved."])
    elif rc.SERVFAIL in (ca, cb) and rc.SUCCESS in (ca, cb):
        sf, ok = (na, nb) if ca == rc.SERVFAIL else (nb, na)
        add("warning", f"Only {sf} returned SERVFAIL",
            f"{ok} resolved the name, so its authoritative servers were reachable at least from {ok}. "
            f"The failure at {sf} may be transient or related to differences in validation or cache state.",
            [f"Retry with {sf} later.", "Compare DNSSEC behaviour with `dig +cd`."])
    elif ca == cb == rc.NODATA:
        add("info", f"Both resolvers: no {record_type} record",
            f"Both resolvers agree that {domain} exists but has no {record_type} record.",
            [f"Try the {'A' if record_type == 'AAAA' else 'AAAA'} record type."])
    elif ca != cb:
        add("info", "Resolvers returned different outcomes",
            f"{na}: {da['status']}; {nb}: {db['status']}. Differences between resolvers are reported as an "
            "observation; they can arise from caching, timing or policy and are not automatically an error.")
    return out


def diagnose_test(result: dict) -> dict:
    """
    Produce the full diagnostic report for a completed test result as built by
    ``services.run_dns_test`` (keys: domain, record_type, timeout, resolvers,
    attempts, comparison).
    """
    domain = result["domain"]
    record_type = result["record_type"]
    timeout = result.get("timeout", 2.0)
    meta = {k: v for k, v in result["resolver_meta"].items()}
    summaries = {k: result["comparison"]["resolvers"][k]["summary"] for k in result["attempts"]}

    per_resolver = {
        key: diagnose_resolver(meta[key], summaries[key], result["attempts"][key], domain, record_type, timeout)
        for key in result["attempts"]
    }
    cross = _cross_resolver(per_resolver, summaries, meta, domain, record_type)

    worst = max((d["severity"] for d in per_resolver.values()), key=lambda s: SEVERITY_ORDER.get(s, 0),
                default="info")
    categories = {d["category"] for d in per_resolver.values()}
    if categories == {rc.SUCCESS}:
        headline = f"{domain} resolved successfully"
    elif len(categories) == 1:
        only = next(iter(per_resolver.values()))
        title, status = only["title"], only["status"]
        headline = title if status.split(" ")[0].lower() in title.lower() else f"{status}: {title}"
    else:
        headline = "Resolvers produced different outcomes"

    return {
        "severity": worst,
        "headline": headline,
        "resolvers": per_resolver,
        "cross_resolver": cross,
        "disclaimer": DISCLAIMER,
    }


def outcome_label(result: dict) -> str:
    """Short outcome label stored in history."""
    cats = {s["summary"]["dominant_category"] for s in result["comparison"]["resolvers"].values()}
    mixed = any(s["summary"]["mixed_outcomes"] for s in result["comparison"]["resolvers"].values())
    if cats == {rc.SUCCESS} and not mixed:
        return "SUCCESS"
    if len(cats) == 1 and not mixed:
        return next(iter(cats))
    if rc.SUCCESS in cats or any(s["summary"]["successful"] for s in result["comparison"]["resolvers"].values()):
        return "PARTIAL"
    return "FAILED"
